"""Prepare published basic-level samples; never label them V01–V30 variants."""
from pathlib import Path
import re,json,hashlib,zipfile,shutil
root=Path(__file__).resolve().parents[1]
inputs=root/'reports/practice-inputs-v3'
notes=json.loads((inputs/'inspection.json').read_text(encoding='utf-8'))
def clean(text):
 text=re.sub(r'=== PAGE \d+ ===\s*\d+\s*','',text)
 text=re.sub(r'[ \t]+',' ',text)
 text=re.sub(r'\n\s*\n','\n',text)
 return text.strip()
def hints(slug,year,n):
 if slug=='is':
  rows={
   1:('Спроектировать структуру производственного учёта по документам заказчика.', ['ER-диаграмма сохранена в PDF.','Отражены таблицы, атрибуты, первичные и внешние ключи.','Проверены 3НФ и ссылочная целостность.'],['Сначала откройте документы заказчика: названия объектов и повторяющиеся поля помогут выделить сущности.','Отделите заказ от его строк, а продукцию — от состава. В 2027 учитывайте также технологические операции.','Проверьте, можно ли восстановить каждую строку исходного документа через связи вашей схемы.']),
   2:('Создать базу по собственной ER-диаграмме и импортировать заказчиков.', ['Созданы сущности, отношения и ограничения по диаграмме.','Импортирован исходный Заказчики.json.','Ключи и связи проверены после импорта.'],['Нужен собственный результат задания 1. Сначала создайте родительские таблицы, затем зависимые.','Сопоставьте имена JSON-полей с вашей схемой. Идентификаторы с ведущими нулями не превращайте в число без обоснования.','Сравните количество записей до и после импорта; проверьте пустые значения и роли заказчиков.']),
   3:('Вычислить полную стоимость заказа по составу продукции.', ['Запрос учитывает количество продукции в заказе.','Учтены нормы расхода и цены всех материалов.' if year==2026 else 'Учтены нормы расхода, стоимость материалов и технологических операций.','Результат одного заказа сверен ручным расчётом.'],['Нужна база из задания 2 с данными предметной области. Готовая база не подставляется вместо вашей работы.','Проверьте соединения до суммирования: лишнее соединение может умножить строки и стоимость.','В 2027 стоимость складывается из материалов и операций; учебный пример 2026 только про материалы не покрывает всё задание 2027.']),
   4:('Создать авторизацию, проверку пазлом и управление пользователями.', ['Проверяются обязательные логин и пароль, сообщения соответствуют условию.','Пазл проверяется, три неудачные попытки приводят к блокировке.','Администратор добавляет и изменяет пользователей, снимает блокировку.','Повторяющийся логин отклоняется; ошибки не завершают приложение аварийно.'],['Откройте техническое задание и изображения. Отдельно выпишите переходы: успешный вход, ошибка, блокировка, снятие блокировки.','Разделите проверку данных, изменение счётчика попыток и отображение сообщения. Роль пользователя должна влиять на доступные действия.','Пройдите сценарии обычного пользователя и администратора; проверьте третью ошибку, а не только первую.']),
  }
  if year==2027 and n==5:return ('Разработать API заметок и коллекцию запросов с тестами.', ['Таблица notes связана с users, добавлены 3–5 тестовых заметок.','GET /notes или /api/notes возвращает id, title_user, content, formatted_date.','title_user имеет вид «заголовок - логин», дата — ДД.ММ.ГГГГ.','Обработаны 400, пустой массив с 200 и ошибка сервера с 500.','В коллекции есть тесты статуса 200, статуса 500 и валидности JSON.'],['Откройте Приложение 2: здесь требуется API заметок, а не демонстрационный каталог из конструктора стеков.','Сначала проверьте связь notes.Id_user → users, затем преобразуйте каждую запись в контракт ответа. Не отдавайте необработанную строку базы.','Для теста 500 используйте контролируемый сбой тестовой базы; не ломайте основную рабочую базу. Сохраните коллекцию запросов.'])
  if n==(6 if year==2027 else 5):return ('Описать реализованный API по приложенному шаблону.' if year==2027 else 'Описать назначение реализованного функционала и методы.', ['Описаны реально реализованные методы и их параметры.','Указаны базовый URL, форматы ответов и коды HTTP.' if year==2027 else 'Объяснено функциональное назначение приложения.','Приведены примеры запросов и ответов; сохранён исходный шаблон.' if year==2027 else 'Документация согласована с текущей версией программы.'],['Документируйте собственный результат предыдущих заданий, а не предполагаемую будущую реализацию.','В 2027 используйте именно переданный Word-шаблон: базовый URL, методы, параметры и HTTP-коды. В 2026 этот API-шаблон не требуется.','Повторите описанный вызов и сопоставьте фактический результат с документацией.'])
  return rows[n]
 if slug=='web':
  if n==1:return ('Создать работающее приложение с базой, регистрацией, заявками и панелью администратора.', ['Создана база и ER-диаграмма.','Регистрация, авторизация и валидация реализованы по условию.','Пользователь видит свои заявки; администратор меняет их статус.','Исходники и коммиты сохранены в назначенном репозитории.'],['Выпишите роли и допустимые действия для каждой страницы.','Сначала проведите одну заявку по всей цепочке: пользователь → база → администратор.','Учтите точные требования выбранного года к полям, форматам, статусам и доступу администратора.'])
  if n==2:return ('Доработать дизайн и формы приложения для экрана 390×844.', ['Подготовлен дизайн всех страниц для 390×844.','Ошибки валидации отображаются в форме, отзывы ограничены завершёнными событиями.','Заявка и панель администратора доработаны по условию.','Слайдер содержит четыре изображения, переключение каждые 3 секунды и кнопки вперёд/назад.' if year==2026 else 'Графика оптимизирована, элементы формы и карточки заявок согласованы.'],['Используйте приложение и материалы задания 1, сохраняя роли и данные.','Проверьте все страницы на узком экране, включая длинные ошибки и пустые списки.','Слайдер — обязательная часть образца 2026. Не переносите это требование автоматически в 2027.'])
  return ('Интегрировать адаптивный дизайн, интерактивность и доработки базы.', ['База поддерживает задачи предыдущих заданий.','Адаптивный дизайн интегрирован в работающее приложение.','Добавлены анимации и микроанимации без нарушения сценариев.','Результаты сохранены в репозитории.'],['Продолжайте тот же проект и ту же базу.','Повторите полный сценарий с регистрацией, заявкой и изменением статуса после интеграции дизайна.','Проверьте, что анимация не скрывает сообщения и не мешает нажать кнопку.'])
 if n==1:return ('Разработать базу учёта обуви и загрузить предоставленные данные.', ['ER-диаграмма в PDF содержит связи и ключи.','Данные import загружены в базу с сохранением отношений.','Сохранён скрипт БД или конфигурация .dt для 1С.'],['Откройте описание предметной области и файлы import.','Импортируйте справочники до зависимых строк; не меняйте смысл связей.','Проверьте восстановление сохранённой базы на отдельном тестовом экземпляре.'])
 if n==2:return ('Реализовать алгоритм и каталог товаров с расчётом цены.', ['Каталог получает данные из базы и использует изображение-заглушку.','Оформление соответствует руководству по стилю.','Алгоритм, авторизация и цветовые правила реализованы по образцу 2026.' if year==2026 else 'Скидка 25% зависит от отсутствия заказов в предыдущем календарном месяце.','Приложение не завершается аварийно при проверке.'],['Прочитайте требования выбранного года: алгоритмы скидки 2026 и 2027 различаются.','Проверьте граничные значения остатков и скидок. Для 2027 отдельно проверьте переход декабря в январь.','Готовый учебный расчёт после фиксированной скидки не заменяет весь каталог и правило отбора товаров.'])
 if n==3:return ('Доработать последовательный интерфейс и управление товарами.' if year==2026 else 'Реализовать поиск, фильтрацию, сортировку и оформление заказа.', ['Навигация и сообщения об ошибках работают.','Поиск и фильтр применяются совместно, сортировка сохраняется.','Добавление, изменение и удаление товара доступны только администратору; заказанный товар удалить нельзя.' if year==2026 else 'Авторизованный пользователь выбирает модель, размер, количество и подтверждает заказ.','После изменения данных список и остатки обновляются.'],['Используйте базу и приложение предыдущих заданий.','Составьте матрицу прав по ролям и проверьте каждую роль отдельно.','Сначала примените фильтр, затем поиск, затем сортировку и убедитесь, что условия работают совместно.'])
 return ('Добавить работу с заказами для менеджера и администратора.', ['Отображаются дата заказа и ФИО клиента.','Можно просмотреть состав, добавить и удалить позиции по условию.','Администратор изменяет дату заказа и удаляет товарные позиции.','Список обновляется; исходники, БД и README сохранены в репозитории.'],['Продолжайте проект оформления заказа из задания 3.','Различайте права менеджера и администратора.','После каждого изменения проверьте состав заказа, итог и актуальность списка.'])

report=[]
for slug,num in [('is',5),('web',3),('programmer',2)]:
 p=root/'content'/f'{slug}.json';c=json.loads(p.read_text(encoding='utf-8'));c['templateVersion']='0.3.0'
 for y in c['years']:
  year=y['year'];name=f'{year}_{"КОД" if year==2026 else "КИМ"} 09.02.07-{num}-{year} Том 1.txt'
  text=(root/'reports/sources'/name).read_text(encoding='utf-8')
  start=text.index('Образец задания для ГИА ДЭ БУ'); section=text[start:]
  end=re.search(r'Образец задания для ГИА ДЭ ПУ|3\.6\s+Примерный',section)
  assert end;section=section[:end.start()]
  matches=list(re.finditer(r'(?:Модуль|Задание)\s+(\d+)\.',section));assert len(matches)==len(y['modules']),(slug,year,len(matches))
  dest=root/'practice-assets'/slug/str(year);dest.mkdir(parents=True,exist_ok=True)
  tasks=[];all_files={}
  for i,m in enumerate(matches):
   n=int(m.group(1));task_id=f'M{n}';chunk=section[m.start():matches[i+1].start() if i+1<len(matches) else len(section)]
   before=text[:start+m.start()];page=int(list(re.finditer(r'=== PAGE (\d+) ===',before))[-1].group(1))
   summary,checks,help_=hints(slug,year,n)
   task_files=[];task_folder=inputs/slug/str(year)/'БУ'/f'{"Модуль" if year==2026 else "Задание"} {n}'
   for f in sorted(task_folder.rglob('*')) if task_folder.exists() else []:
    if not f.is_file() or f.suffix.lower() in ('.rar','.zip'):continue
    rel=Path('assets')/task_id/f.name;assert rel.as_posix() not in all_files
    target=dest/rel;target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(f,target)
    all_files[rel.as_posix()]=f.read_bytes()
    task_files.append({'name':f.name,'url':f'practice/{year}/{rel.as_posix()}','size':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
   supplements=[{'title':Path(r['path']).name,'text':r['text']} for r in notes if r['path'].startswith(str(task_folder.relative_to(inputs))) and Path(r['path']).suffix in ('.pdf','.docx') and 'text' in r]
   dependencies={1:[],2:['M1'],3:['M2'],4:['M2'],5:['M4'],6:['M5']}[n] if slug=='is' else [f'M{j}' for j in range(1,n)]
   tasks.append({'id':task_id,'number':n,'title':y['modules'][i]['title'],'seconds':y['modules'][i]['durationSeconds'],'page':page,'text':clean(chunk),'summary':summary,'checks':checks,'hints':help_,'files':task_files,'supplements':supplements,'dependsOn':dependencies,'zip':f'practice/{year}/task-{n}.zip'})
  # Full sample archive carries only the applicable basic-level materials and no answers.
  readme=f'# Пробный экзамен по опубликованному образцу\n\n{c["specialty"]} · {c["qualification"]}\n{y["documentCode"]} · ГИА · базовый уровень\n\nЭто один опубликованный образец, не индивидуальный V01–V30 и не реальная сдача.\nНорматив: {y["totalSeconds"]//60} минут; максимум {y["assessment"]["maxPoints"]:g} баллов.\n\nРаботайте в одном проекте, последующие задания используют ваши результаты предыдущих. Готовая БД и решения не подставляются. Требования к программам и передаче результата сохранены в условии. Учебный сайт не принимает файлы и не выставляет оценки.\n\nИзвлечение текста может не передавать изображения и вёрстку: исходный PDF приложен и является окончательным источником. Все вложенные архивы распакованы; исходные файлы не изменены.\n'
  task_text='\n\n'.join(f'## {t["id"]} · стр. {t["page"]}\n\n'+t['text'] for t in tasks)
  full={**all_files,'Начните здесь.md':readme,'Условия.md':task_text,'Источник.pdf':(root/'source-documents'/slug/f'{year}.pdf').read_bytes()}
  full['manifest.json']=json.dumps({'sampleId':f'published-{slug}-{year}','sourceSHA256':y['source']['sha256'],'tasks':[t['id'] for t in tasks],'files':[{'path':k,'sha256':hashlib.sha256(v).hexdigest()} for k,v in all_files.items()]},ensure_ascii=False,indent=2)
  def writezip(file,files):
   with zipfile.ZipFile(file,'w',zipfile.ZIP_DEFLATED) as z:
    for k,v in files.items():z.writestr(k,v)
   with zipfile.ZipFile(file) as z:assert z.testzip() is None
  writezip(dest/'sample.zip',full)
  for t in tasks:
   selected={k:v for k,v in all_files.items() if int(k.split('/')[1][1:])<=t['number']}
   selected.update({'Начните здесь.md':readme+'\nТренировка одного задания: '+t['title']+'\nПредыдущие исходные материалы включены для контекста; собственные выполненные предыдущие задания необходимо подготовить самостоятельно.','Условие.md':t['text'],'Источник.pdf':full['Источник.pdf']})
   writezip(dest/f'task-{t["number"]}.zip',selected)
  y['practice']={'version':'published-sample-1','id':f'published-{slug}-{year}','label':'Опубликованный образец '+str(year),'kind':'published-sample','ready':True,'tasks':tasks,'zip':f'practice/{year}/sample.zip','assetCount':len(all_files),'notice':'Один образец из документа с исходными приложениями. Это не 30 полных индивидуальных вариантов.','sourcePages':f'{tasks[0]["page"]}–{int(list(re.finditer(r"=== PAGE (\d+) ===",text[:start+end.start()]))[-1].group(1))}'}
  report.append({'site':slug,'year':year,'tasks':len(tasks),'assets':len(all_files),'pages':[t['page'] for t in tasks]})
 p.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(root/'reports/practice-build.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(report,ensure_ascii=False,indent=2))
